        S('Lecture photo: line profiles', figfit('s10_line_widths', 'Lecture slide: absorption line profiles as a function of altitude, limb spectra for tangent heights 17–65 km.', 520, 700, 'jpg', 'slides')),
        S('A.6 DOAS: separating slow and fast structures', cols(figfit('f21_doas_principle', 'Figure 10: I₀, I′₀ and the differential absorption D.', 440, 560),
          fm('σ = σ<sub>b</sub> + σ′', 34) + fm('D = ln(I′<sub>0</sub>/I) = σ′ · c · L', 30) + '<p class="note">σ′ is the gas fingerprint; σ<sub>b</sub> goes to the polynomial.</p>', flex=[1, 1])),
        S('Lecture photo: DOAS', figfit('s11_doas', 'Lecture slide: Differential Optical Absorption Spectroscopy.', 520, 700, 'jpg', 'slides')),
